new file mode 100644
index 000000000..30fb9dad6
--- /dev/null
+++ b/cmd/internal/detachmeasure/trace.go
@@ -0,0 +1,216 @@
+// Package detachmeasure exists only in this disposable measurement clone.
+package detachmeasure
+
+import (
+	"context"
+	"crypto/sha256"
+	"encoding/json"
+	"fmt"
+	"os"
+	"runtime"
+	"sync"
+	"sync/atomic"
+	"syscall"
+	"time"
+)
+
+type Row struct {
+	Event        string   `json:"event"`
+	Thread       string   `json:"thread,omitempty"`
+	Key          string   `json:"key,omitempty"`
+	ID           uint64   `json:"id,omitempty"`
+	TimeNS       int64    `json:"time_ns"`
+	StartedNS    int64    `json:"started_ns,omitempty"`
+	DurationNS   int64    `json:"duration_ns,omitempty"`
+	Args         []string `json:"args,omitempty"`
+	Failed       bool     `json:"failed,omitempty"`
+	Parallelism  int      `json:"parallelism,omitempty"`
+	UserCPU_NS   int64    `json:"user_cpu_ns,omitempty"`
+	SystemCPU_NS int64    `json:"system_cpu_ns,omitempty"`
+}
+
+var state struct {
+	sync.Mutex
+	active   bool
+	started  bool
+	total    int
+	rows     []Row
+	overhead int64
+	overflow bool
+	cpu      syscall.Rusage
+	stack    []byte
+}
+var ids atomic.Uint64
+
+func Enabled() bool          { return os.Getenv("PAIR_DETACH_MEASURE_LOG") != "" }
+func NextID() uint64         { return ids.Add(1) }
+func Key(path string) string { return fmt.Sprintf("%x", sha256.Sum256([]byte(path)))[:16] }
+
+type threadKey struct{}
+
+func WithThread(ctx context.Context, thread string) context.Context {
+	return context.WithValue(ctx, threadKey{}, thread)
+}
+func Thread(ctx context.Context) string { value, _ := ctx.Value(threadKey{}).(string); return value }
+func Start() {
+	if !Enabled() {
+		return
+	}
+	state.Lock()
+	defer state.Unlock()
+	state.active = true
+	state.started = true
+	_ = syscall.Getrusage(syscall.RUSAGE_SELF, &state.cpu)
+}
+func Add(row Row) {
+	if !Enabled() {
+		return
+	}
+	begun := time.Now()
+	if row.TimeNS == 0 {
+		row.TimeNS = begun.UnixNano()
+	}
+	state.Lock()
+	defer state.Unlock()
+	if !state.active && row.Event != "console.lifecycle.queue" {
+		return
+	}
+	if state.total < 4096 {
+		state.total++
+		state.rows = append(state.rows, row)
+	} else {
+		state.overflow = true
+	}
+	state.overhead += time.Since(begun).Nanoseconds()
+}
+func Record(event, key string, elapsed time.Duration) {
+	Add(Row{Event: event, Thread: key, DurationNS: int64(elapsed)})
+}
+func Timer(event, key string, id uint64) func() {
+	if !Enabled() {
+		return func() {}
+	}
+	begun := time.Now()
+	return func() {
+		end := time.Now()
+		Add(Row{Event: event, Thread: key, ID: id, StartedNS: begun.UnixNano(), TimeNS: end.UnixNano(), DurationNS: end.Sub(begun).Nanoseconds()})
+	}
+}
+func CPU() {
+	var end syscall.Rusage
+	err := syscall.Getrusage(syscall.RUSAGE_SELF, &end)
+	state.Lock()
+	begin := state.cpu
+	state.Unlock()
+	delta := func(a, b syscall.Timeval) int64 { return (a.Sec-b.Sec)*1e9 + int64(a.Usec-b.Usec)*1000 }
+	Add(Row{Event: "whole_leave.process_cpu", UserCPU_NS: delta(end.Utime, begin.Utime), SystemCPU_NS: delta(end.Stime, begin.Stime), Failed: err != nil})
+}
+func Flush()      { flush(false) }
+func FinalFlush() { flush(true) }
+func flush(final bool) {
+	if !Enabled() {
+		return
+	}
+	begun := time.Now()
+	state.Lock()
+	if !state.started {
+		state.Unlock()
+		return
+	}
+	if final {
+		state.active = false
+	}
+	rows := append([]Row(nil), state.rows...)
+	state.rows = nil
+	overhead, overflow := state.overhead, state.overflow
+	state.Unlock()
+	stats := map[string]any{"started_ns": begun.UnixNano(), "final": final}
+	var errs []error
+	phase := func(name string, f func() error) {
+		start := time.Now()
+		err := f()
+		stats[name+"_ns"] = time.Since(start).Nanoseconds()
+		if err != nil {
+			errs = append(errs, err)
+		}
+	}
+	var f *os.File
+	path := os.Getenv("PAIR_DETACH_MEASURE_LOG")
+	phase("open", func() (err error) { f, err = os.OpenFile(path, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0600); return })
+	if f == nil {
+		fmt.Fprintln(os.Stderr, "measurement open failed")
+		return
+	}
+	encoder := json.NewEncoder(f)
+	phase("data_write", func() error {
+		for _, r := range rows {
+			if err := encoder.Encode(r); err != nil {
+				return err
+			}
+		}
+		return nil
+	})
+	phase("data_sync", f.Sync)
+	phase("footer_write", func() error {
+		return encoder.Encode(map[string]any{"event": "instrumentation", "observer_ns": overhead, "overflow": overflow, "final": final, "rows": len(rows)})
+	})
+	phase("footer_sync", f.Sync)
+	phase("close", f.Close)
+	stats["finished_ns"] = time.Now().UnixNano()
+	stats["total_ns"] = time.Since(begun).Nanoseconds()
+	stats["failed"] = len(errs) > 0
+	if final {
+		state.Lock()
+		stack := state.stack
+		state.Unlock()
+		if len(stack) > 0 {
+			phase("stack_write", func() error { return os.WriteFile(path+".stack.txt", stack, 0600) })
+		}
+		data, _ := json.Marshal(stats)
+		_ = os.WriteFile(path+".final-flush.json", append(data, '\n'), 0600)
+	} else {
+		for name, value := range stats {
+			if elapsed, ok := value.(int64); ok {
+				Add(Row{Event: "flush.leave." + name, DurationNS: elapsed})
+			}
+		}
+	}
+	if len(errs) > 0 {
+		fmt.Fprintln(os.Stderr, "measurement flush:", errs)
+	}
+}
+
+func WatchMessageClose() func() {
+	state.Lock()
+	active := state.active
+	state.Unlock()
+	if !active {
+		return func() {}
+	}
+	done, joined := make(chan struct{}), make(chan struct{})
+	go func() {
+		defer close(joined)
+		timer := time.NewTimer(100 * time.Millisecond)
+		defer timer.Stop()
+		select {
+		case <-done:
+			return
+		case <-timer.C:
+		}
+		select {
+		case <-done:
+			return
+		default:
+		}
+		begun := time.Now()
+		buf := make([]byte, 512<<10)
+		n := runtime.Stack(buf, true)
+		state.Lock()
+		if state.stack == nil {
+			state.stack = buf[:n]
+		}
+		state.Unlock()
+		Add(Row{Event: "messages.Close.stack", StartedNS: begun.UnixNano(), DurationNS: time.Since(begun).Nanoseconds(), Key: fmt.Sprint(n), Failed: n == len(buf)})
+	}()
+	return func() { close(done); <-joined }
+}
